/**
 * Quran Stories Seed Data — First Batch
 *
 * CONTENT POLICY:
 * ───────────────
 * - Every story has at least one Quran reference with valid surah:ayah range
 * - No Arabic text is embedded as a string literal (arabicText field is omitted)
 * - All summaries are labeled "translation" where applicable
 * - All source IDs map to entries in sourceRegistry.ts
 * - All segments carry sunniReview status = "needs_review" until formally verified
 * - Kids summaries use simple language and avoid complex theological detail
 * - Adult summaries reference specific tafsir sources without reproducing their text
 * - No extra-Quranic details (Israiliyyat) are included
 * - Related stories are linked only where there is clear Quranic evidence
 *
 * FIRST BATCH (8 stories):
 * 1. Yusuf عليه السلام (Surah Yusuf — complete in one surah)
 * 2. Musa عليه السلام and Pharaoh (multiple surahs)
 * 3. People of the Cave (Surah Al-Kahf)
 * 4. Ibrahim عليه السلام — idols and fire (Surah Al-Anbiya, Al-Baqarah)
 * 5. Nuh عليه السلام (Surah Nuh, Hud, and others)
 * 6. Sulayman عليه السلام and Bilqis (Surah Al-Naml)
 * 7. Maryam عليها السلام (Surah Maryam, Aal-Imran)
 * 8. Luqman's Advice (Surah Luqman)
 *
 * STATUS: All segments are "needs_review" — not approved for production display
 * without scholarly review. UI must show the needs_review warning for all segments.
 */

