      summaryAdultsEnglish: "Surah Al-Araf (7:20-22) describes the method of whispering: swearing falsely by Allah and claiming to give sincere advice. Humans weaken before doubt dressed as benefit. Allah said (20:115): 'And We found in him no firm resolve' — it was not wilful disobedience but forgetfulness and weakness of resolve. The difference between Adam's error and Iblis's: Adam repented, Iblis persisted. [Reference: Tafsir Ibn Kathir and Al-Tabari — 7:20-22 and 20:115, needs verification]",
      lessonsArabic: ['الشيطان يستخدم الحلف بالله لتجميل الكذب', 'الضعف الإنساني أمام الشبهة جُبل في طبيعتنا — والتوبة هي المخرج', 'فرق بين الزلة والإصرار: الأول يُغفر والثاني يُهلك'],
      lessonsEnglish: ["Satan uses swearing by Allah to beautify falsehood", "Human weakness before doubt is part of our nature — repentance is the way out", "There is a difference between slipping and insisting: the first is forgiven, the second destroys"],
