export function getStoryById(storyId: string): QuranStory | undefined {
  return QURAN_STORIES_FIRST_BATCH.find((s) => s.storyId === storyId);
}

export function getStoriesByTheme(theme: string): QuranStory[] {
  return QURAN_STORIES_FIRST_BATCH.filter((s) => s.themes.includes(theme));
}

export function getStoriesByProphet(prophetName: string): QuranStory[] {
  return QURAN_STORIES_FIRST_BATCH.filter(
    (s) =>
      s.prophetsMentioned?.includes(prophetName) ||
      s.mainCharacters.includes(prophetName)
  );
}

export function getRelatedStories(storyId: string): QuranStory[] {
  const story = getStoryById(storyId);
  if (!story) return [];

  return story.relatedStories
    .map((rel) => getStoryById(rel.storyId))
    .filter((s): s is QuranStory => s !== undefined);
}
